/**
 * The networks of the home-page animation. Each visit picks one at random; the data
 * (`public/landing-networks/<id>.json`) is generated by `npm run landing:network` from the GTFS
 * feed imported from the catalog. The id is that of the catalog entry.
 */
export interface LandingNetworkConfig {
  /** Catalog entry (`shared/catalog.ts`). */
  id: string;
  /** City centre, to know which line ends are "outside" and get labelled. */
  center: [lat: number, lon: number];
  /** Simulated window, in seconds since midnight (default: 07:00 to 10:00). */
  window?: [number, number];
  /** Lines (route_short_name) that are not drawn: far from the rest or without a usable path. */
  skip?: string[];
  /** Route types that are drawn (default: all). */
  routeTypes?: number[];
}

export const LANDING_NETWORKS: LandingNetworkConfig[] = [
  { id: 'fgc', center: [41.3874, 2.1686], skip: ['RL1', 'RL2', 'BusBV', 'L1'] },
  { id: 'mta-subway', center: [40.758, -73.9855] },
  { id: 'atm-milano', center: [45.4642, 9.19], routeTypes: [1] },
  { id: 'tisseo', center: [43.6047, 1.4442], routeTypes: [0, 1] },
  { id: 'metrovalencia', center: [39.4699, -0.3763] },
  { id: 'bart', center: [37.7749, -122.4194], routeTypes: [1] },
  { id: 'lametro-rail', center: [34.0522, -118.2437] },
];

/** A network's data, as written by the generator and read by the animation. */
export interface LandingNetwork {
  id: string;
  /** Dia simulat (AAAAMMDD). */
  date: string;
  window: [number, number];
  width: number;
  height: number;
  /** City centre in drawing coordinates: labels move away from it. */
  center: [number, number];
  lines: { name: string; color: string; text: string; d: string }[];
  /** Line ends far from the centre, with the lines that end there. */
  labels: { x: number; y: number; lines: number[] }[];
  /** [line, departure, arrival, start fraction, end fraction] along the path. */
  trains: [number, number, number, number, number][];
}
